      }
    } catch { /* not a directory */ }
  }
  console.log(`  ✅ ${sampleCount} samples loaded`);
}

// ── Waveform generators ──
const waveMap = {
  sine: 'sine', triangle: 'triangle', square: 'square',
  sawtooth: 'sawtooth', saw: 'sawtooth', tri: 'triangle',
};

function noteToFreq(note) {
  if (typeof note === 'number') return note;
  const m = String(note).match(/^([a-gA-G])(#|b|s)?(\d+)?$/);
  if (!m) return 440;
  const map = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
  let semi = map[m[1].toLowerCase()] ?? 0;
  if (m[2] === '#' || m[2] === 's') semi++;
  if (m[2] === 'b') semi--;
  const oct = parseInt(m[3] ?? '4');
  return 440 * Math.pow(2, (semi - 9 + (oct - 4) * 12) / 12);
}

function noteToMidi(note) {
  if (typeof note === 'number') return note;
  const m = String(note).match(/^([a-gA-G])(#|b|s)?(\d+)?$/);
  if (!m) return 60;
  const map = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
  let semi = map[m[1].toLowerCase()] ?? 0;
  if (m[2] === '#' || m[2] === 's') semi++;
  if (m[2] === 'b') semi--;
  const oct = parseInt(m[3] ?? '4');
  return semi + (oct + 1) * 12; // C4 = MIDI 60
}

function noteToSemitones(note) {
  return noteToMidi(note) - 60;
}

// ── Pitch-shift utilities ──

/**
 * Detect root note from sample bank name.
 * 
 * Priority:
 * 1. strudel.json manifest (authoritative if present)
 * 2. Filename heuristic: e.g. "bass_Cs1" → MIDI 25 (C#1)
 * 3. Default: MIDI 60 (C3)
 */
function detectRootNote(sampleName) {
  // 1. Check strudel.json manifest first (authoritative)
  if (strudelRootNotes.has(sampleName)) {
    return strudelRootNotes.get(sampleName);
  }

  // 2. Try to match a trailing note name like _Cs1, _A1, _Fs2 etc.
  const m = String(sampleName).match(/[_-]([A-Ga-g])(s|#|b)?(\d+)$/);
  if (m) {
    const map = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
    let semi = map[m[1].toLowerCase()] ?? 0;
    if (m[2] === 's' || m[2] === '#') semi++;
    if (m[2] === 'b') semi--;
    const oct = parseInt(m[3]);
    return semi + (oct + 1) * 12;
  }

  // 3. Default
  return 60; // C3 / MIDI 60
}

/**
 * Check if a sample name indicates a percussive sound.
 * Percussive sounds get simple resampling (speed change).
 * Tonal sounds get duration-preserving granular pitch shift.
 */
const PERC_PATTERNS = /kick|hat|clap|snare|perc|rim|tom|crash|ride|cymbal|808bd|808hc|808oh|808sd|bd|sd|hh|cp|cb|cr|ht|lt|mt|ghost/i;
function isPercussive(sampleName) {
  return PERC_PATTERNS.test(sampleName);
}

/**
 * Simple resampling by playback rate ratio (percussive mode).
 * ratio > 1 = higher pitch, shorter duration.
 * ratio < 1 = lower pitch, longer duration.
 * Uses linear interpolation.
 */
function resampleBuffer(float32Buf, ratio) {
  if (Math.abs(ratio - 1.0) < 0.001) return float32Buf;
  const outLen = Math.round(float32Buf.length / ratio);
  if (outLen <= 0) return new Float32Array(0);
  const out = new Float32Array(outLen);
  for (let i = 0; i < outLen; i++) {
    const srcIdx = i * ratio;
    const idx0 = Math.floor(srcIdx);
    const frac = srcIdx - idx0;
    const s0 = idx0 < float32Buf.length ? float32Buf[idx0] : 0;
    const s1 = idx0 + 1 < float32Buf.length ? float32Buf[idx0 + 1] : s0;
    out[i] = s0 * (1 - frac) + s1 * frac;
  }
  return out;
}

/**
 * Duration-preserving pitch shift (tonal mode).
 *
 * Two-step approach:
 * 1. Resample the buffer by the pitch ratio (changes both pitch AND duration)
 * 2. Time-stretch back to original length using WSOLA (Waveform Similarity
 *    Overlap-Add) to restore the original duration
 *
 * @param {Float32Array} input - mono audio buffer
 * @param {number} ratio - pitch ratio (>1 = higher, <1 = lower)
 * @param {number} sr - sample rate
 * @returns {Float32Array} pitch-shifted buffer of same length
 */
function granularPitchShift(input, ratio, sr) {
  if (Math.abs(ratio - 1.0) < 0.001) return input;

  // Step 1: Resample by pitch ratio (changes pitch + duration)
  const resampled = resampleBuffer(input, ratio);

  // Step 2: Time-stretch back to original length using WSOLA
  const targetLen = input.length;
  return wsolaStretch(resampled, targetLen, sr);
}

/**
 * WSOLA (Waveform Similarity Overlap-Add) time stretching.
 * Stretches or compresses audio to targetLen without changing pitch.
 *
 * @param {Float32Array} input - audio to stretch
 * @param {number} targetLen - desired output length in samples
 * @param {number} sr - sample rate
 * @returns {Float32Array} time-stretched audio
 */
function wsolaStretch(input, targetLen, sr) {
  if (input.length === 0) return new Float32Array(targetLen);
  if (Math.abs(input.length - targetLen) < 2) {
    const out = new Float32Array(targetLen);
    out.set(input.subarray(0, Math.min(input.length, targetLen)));
    return out;
  }

  const stretchRatio = targetLen / input.length;

  // Fixed grain size tuned for musical content (80ms works well for ≥100 Hz)
  const grainLen = Math.round(sr * 0.08); // 80ms
  const synthHop = Math.round(grainLen / 4); // 75% overlap
  const analysisHop = Math.max(1, Math.round(synthHop / stretchRatio));
  const tolerance = Math.round(grainLen / 4);

  const output = new Float32Array(targetLen);
  const normBuf = new Float32Array(targetLen);

  // Hanning window
  const win = new Float32Array(grainLen);
  for (let i = 0; i < grainLen; i++) {
    win[i] = 0.5 * (1 - Math.cos(2 * Math.PI * i / (grainLen - 1)));
  }

  let readPos = 0;

  for (let writePos = 0; writePos < targetLen; writePos += synthHop) {
    // WSOLA: find best overlap offset within tolerance
    let bestOffset = 0;
    if (writePos >= synthHop) {
      let bestCorr = -Infinity;
      const minOff = Math.max(-tolerance, -Math.round(readPos));
      const maxOff = Math.min(tolerance, input.length - Math.round(readPos) - grainLen);

      for (let off = minOff; off <= maxOff; off++) {
        let corr = 0;
        const ri = Math.round(readPos) + off;
        // Cross-correlate start of this grain with end of previous grain overlap
        const prevStart = writePos - synthHop;
        const checkLen = Math.min(synthHop, grainLen);
        for (let j = 0; j < checkLen; j++) {
          const inIdx = ri + j;
          const outIdx = prevStart + j;
          if (inIdx >= 0 && inIdx < input.length && outIdx >= 0 && outIdx < targetLen && normBuf[outIdx] > 0.001) {
            corr += input[inIdx] * (output[outIdx] / normBuf[outIdx]);
          }
        }
        if (corr > bestCorr) {
          bestCorr = corr;
          bestOffset = off;
        }
      }
    }

    const actualRead = Math.round(readPos + bestOffset);

    for (let i = 0; i < grainLen; i++) {
      const wi = writePos + i;
      if (wi >= targetLen) break;
      const idx = actualRead + i;
      const sample = (idx >= 0 && idx < input.length) ? input[idx] : 0;
      const w = win[i];
      output[wi] += sample * w;
      normBuf[wi] += w * w;
    }

    readPos += analysisHop;
  }

  // Normalize
  for (let i = 0; i < targetLen; i++) {
    if (normBuf[i] > 0.001) {
      output[i] /= normBuf[i];
    }
  }

  return output;
}

/**
 * Pitch-shift a multi-channel sample buffer.
 * Returns a new buffer object with shifted data (and possibly different length for percussive mode).
 *
 * @param {Object} sampleBuf - {channels, sampleRate, data[], length}
 * @param {number} semitones - semitone offset (positive = higher pitch)
 * @param {boolean} percussive - use simple resampling (true) or granular (false)
 * @returns {Object} new sample buffer with shifted data
 */
function pitchShiftBuffer(sampleBuf, semitones, percussive) {
  if (Math.abs(semitones) < 0.01) return sampleBuf;

  const ratio = Math.pow(2, semitones / 12);
  const newData = [];

  if (percussive) {
    // Percussive: simple resampling, changes duration
    for (let ch = 0; ch < sampleBuf.channels; ch++) {
      newData.push(resampleBuffer(sampleBuf.data[ch], ratio));
    }
    return {
      channels: sampleBuf.channels,
      sampleRate: sampleBuf.sampleRate,
      data: newData,
      length: newData[0].length,
    };
  } else {
    // Tonal: granular pitch shift, preserves duration
    for (let ch = 0; ch < sampleBuf.channels; ch++) {
      newData.push(granularPitchShift(sampleBuf.data[ch], ratio, sampleBuf.sampleRate));
    }
    return {
      channels: sampleBuf.channels,
      sampleRate: sampleBuf.sampleRate,
      data: newData,
      length: newData[0].length,
    };
  }
}

// ── Software mixer: render haps directly into Float32 buffers ──
// No Web Audio API nodes! Just raw sample mixing.

function renderChunk(startCycle, endCycle, pattern, cps) {
  const chunkStart = startCycle / cps;
  const chunkEnd = endCycle / cps;
  const chunkDur = chunkEnd - chunkStart;
  const numSamples = Math.ceil(chunkDur * sampleRate);

  const left = new Float32Array(numSamples);
  const right = new Float32Array(numSamples);

  const haps = pattern.queryArc(startCycle, endCycle);
  let scheduled = 0;

  for (const hap of haps) {
    const hapStartCycle = hap.part?.begin ?? hap.whole?.begin ?? 0;
    const hapEndCycle = hap.part?.end ?? hap.whole?.end ?? hapStartCycle + 0.25;
    const hapStartSec = hapStartCycle / cps;
    const hapEndSec = hapEndCycle / cps;

    // Convert to chunk-relative time
    const relStart = hapStartSec - chunkStart;
    const relEnd = hapEndSec - chunkStart;

    if (relStart >= chunkDur || relEnd <= 0) continue;

    const v = hap.value;
    if (typeof v !== 'object' || v === null) continue;

    const gain = Math.min(v.gain ?? 0.3, 1.0);
    if (gain <= 0.001) continue;

    const sound = v.s || '';
    const nVal = v.n !== undefined ? Math.round(Number(v.n)) : 0;
    const pan = v.pan ?? 0.5;
    const panL = Math.cos(pan * Math.PI / 2);
    const panR = Math.sin(pan * Math.PI / 2);

    const sampleKey = `${sound}:${nVal}`;
    const sampleBuf = sampleBufferData.get(sampleKey) || sampleBufferData.get(sound);

    if (sampleBuf) {
      // ── Pitch-shift logic ──
      // Determine if we need to pitch-shift this sample
      let activeBuf = sampleBuf;
      let playbackRate = 1.0;

      if (v.note) {
        const targetMidi = noteToMidi(v.note);
        const rootMidi = detectRootNote(sound);
        const semitoneOffset = targetMidi - rootMidi;

        if (Math.abs(semitoneOffset) > 0.01) {
          const perc = isPercussive(sound);
          if (perc) {
            // Percussive mode: playback rate resampling (changes duration)
            playbackRate = Math.pow(2, semitoneOffset / 12);
          } else {
            // Tonal mode: duration-preserving pitch shift via resample + WSOLA
            const cacheKey = `${sound}:${nVal}:ps:${semitoneOffset.toFixed(2)}`;
            let cached = sampleBufferData.get(cacheKey);
            if (!cached) {
              cached = pitchShiftBuffer(sampleBuf, semitoneOffset, false);
              sampleBufferData.set(cacheKey, cached);
              if (!renderChunk._loggedTonal) { renderChunk._loggedTonal = {}; }
              const lk = `${sound}:${v.note}`;
              if (!renderChunk._loggedTonal[lk]) {
                console.log(`  🎵 Pitch-shift: ${sound} note=${v.note} (${semitoneOffset > 0 ? '+' : ''}${semitoneOffset} st)`);
                renderChunk._loggedTonal[lk] = true;
              }
            }
            activeBuf = cached;
          }
        }
      }

      if (v.speed) playbackRate *= Math.abs(v.speed);

      const sampleDur = activeBuf.length / (activeBuf.sampleRate * playbackRate);
      const clipVal = v.clip !== undefined ? Number(v.clip) : 0;
      const effectiveEndSec = clipVal >= 1
        ? relStart + sampleDur
        : Math.min(relEnd, relStart + sampleDur);

      const fadeIn = 0.003;  // 3ms
      const fadeOut = 0.01;  // 10ms

      const startIdx = Math.max(0, Math.floor(relStart * sampleRate));
      const endIdx = Math.min(numSamples, Math.ceil(effectiveEndSec * sampleRate));

      for (let i = startIdx; i < endIdx; i++) {
        const t = i / sampleRate;
        const relT = t - relStart;
        if (relT < 0) continue;

        // Envelope
        let env = gain;
        if (relT < fadeIn) env *= relT / fadeIn;
        const timeToEnd = effectiveEndSec - relStart - relT;
        if (timeToEnd < fadeOut) env *= Math.max(0, timeToEnd / fadeOut);

        // Sample position with playback rate
        const samplePos = relT * activeBuf.sampleRate * playbackRate;
        const sIdx = Math.floor(samplePos);
        if (sIdx >= activeBuf.length) break;

        // Linear interpolation
        const frac = samplePos - sIdx;
        const s0 = activeBuf.data[0][sIdx];
        const s1 = sIdx + 1 < activeBuf.length ? activeBuf.data[0][sIdx + 1] : s0;
        const sample = s0 + frac * (s1 - s0);

        left[i] += sample * env * panL;
        if (activeBuf.channels > 1) {
          const sr0 = activeBuf.data[1][sIdx];
          const sr1 = sIdx + 1 < activeBuf.length ? activeBuf.data[1][sIdx + 1] : sr0;
          right[i] += (sr0 + frac * (sr1 - sr0)) * env * panR;
        } else {
          right[i] += sample * env * panR;
        }
      }
      scheduled++;
    } else if (waveMap[sound]) {
      // Synth oscillator
      let freq = v.freq || (v.note ? noteToFreq(v.note) : 440);
      const oscType = waveMap[sound];
      const attack = v.attack ?? 0.005;
      const decay = v.decay ?? 0.1;
      const sustain = v.sustain ?? 0.7;
      const release = v.release ?? 0.3;

      const startIdx = Math.max(0, Math.floor(relStart * sampleRate));
      const endIdx = Math.min(numSamples, Math.ceil((relEnd + 0.01) * sampleRate));

      for (let i = startIdx; i < endIdx; i++) {
        const t = i / sampleRate;
        const relT = t - relStart;
        if (relT < 0) continue;

        // ADSR
        let env;
        const hapDur = relEnd - relStart;
        if (relT < attack) env = gain * (relT / attack);
        else if (relT < attack + decay) env = gain * (1 - (1 - sustain) * (relT - attack) / decay);
        else if (relT < hapDur - release) env = gain * sustain;
        else env = gain * sustain * Math.max(0, (hapDur - relT) / release);

        // Oscillator
        let sample;
        const phase = relT * freq;
        const frac = phase - Math.floor(phase);
        switch (oscType) {
          case 'sine': sample = Math.sin(2 * Math.PI * phase); break;
          case 'triangle': sample = 4 * Math.abs(frac - 0.5) - 1; break;
          case 'sawtooth': sample = 2 * frac - 1; break;
          case 'square': sample = frac < 0.5 ? 1 : -1; break;
          default: sample = Math.sin(2 * Math.PI * phase);
        }

        left[i] += sample * env * panL;
        right[i] += sample * env * panR;
      }
      scheduled++;
    }
    // else: unrecognized sound, skip
  }

  return { left, right, scheduled, haps: haps.length };
}

// ── Main: chunk loop ──
// Two-pass approach: render into float buffers, find peak, then normalize and write.
console.log(`Rendering ${totalCycles} cycles in chunks of ${chunkSize}...`);

const allFloatChunks = [];  // Store raw float data for normalization pass
let totalScheduled = 0;
let totalHaps = 0;
let globalPeak = 0;

for (let c = 0; c < totalCycles; c += chunkSize) {
  const end = Math.min(c + chunkSize, totalCycles);
  const { left, right, scheduled, haps } = renderChunk(c, end, pattern, actualCps);
  totalScheduled += scheduled;
  totalHaps += haps;

  // Track raw peak levels
  for (let i = 0; i < left.length; i++) {
    const al = Math.abs(left[i]);
    const ar = Math.abs(right[i]);
    if (al > globalPeak) globalPeak = al;
    if (ar > globalPeak) globalPeak = ar;
  }

  allFloatChunks.push({ left, right });

  if ((c / chunkSize) % 5 === 0 || end >= totalCycles) {
    const pct = Math.round(end / totalCycles * 100);
    const memMB = Math.round(process.memoryUsage().heapUsed / 1024 / 1024);
    console.log(`  [${pct}%] Cycles ${c}-${end}: ${scheduled} events scheduled (${memMB}MB heap)`);
  }
}

console.log(`  Total: ${totalScheduled}/${totalHaps} haps scheduled`);
console.log(`  🔊 Raw peak: ${globalPeak.toFixed(4)} (${(20*Math.log10(globalPeak)).toFixed(1)} dBFS)`);

// ── Normalize and convert to 16-bit PCM ──
// Target: -3 dBTP (peak at 0.708) to leave headroom for MP3 encoding
const targetPeak = 0.708; // -3 dBTP
const normGain = globalPeak > 0 ? targetPeak / globalPeak : 1.0;
console.log(`  📐 Normalizing: gain = ${normGain.toFixed(6)} (${(20*Math.log10(normGain)).toFixed(1)} dB)`);

const allPcmChunks = [];
for (const { left, right } of allFloatChunks) {
  const pcm = Buffer.alloc(left.length * 4);
  for (let i = 0; i < left.length; i++) {
    const l = Math.max(-1, Math.min(1, left[i] * normGain));
    const r = Math.max(-1, Math.min(1, right[i] * normGain));
    pcm.writeInt16LE(Math.round(l * 32767), i * 4);
    pcm.writeInt16LE(Math.round(r * 32767), i * 4 + 2);
  }
  allPcmChunks.push(pcm);
}

// Free float buffers
allFloatChunks.length = 0;

// ── Concatenate and write WAV ──
const pcm = Buffer.concat(allPcmChunks);

const wav = makeWav(pcm, sampleRate, 2, 16);
writeFileSync(output, wav);
const durationSec = pcm.length / 4 / sampleRate;
console.log(`✅ ${output} (${(wav.length / 1024 / 1024).toFixed(1)}MB, ${durationSec.toFixed(1)}s)`);
process.exit(0);

function makeWav(pcm, sr, ch, bits) {
  const h = Buffer.alloc(44);
  h.write('RIFF', 0);
  h.writeUInt32LE(36 + pcm.length, 4);
  h.write('WAVE', 8);
  h.write('fmt ', 12);
  h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20);
  h.writeUInt16LE(ch, 22);
  h.writeUInt32LE(sr, 24);
  h.writeUInt32LE(sr * ch * bits / 8, 28);
  h.writeUInt16LE(ch * bits / 8, 32);
  h.writeUInt16LE(bits, 34);
  h.write('data', 36);
  h.writeUInt32LE(pcm.length, 40);
  return Buffer.concat([h, pcm]);
}

#!/usr/bin/env node
/**
 * Offline render v2: Strudel's real audio engine + node-web-audio-api
 * 
 * Evaluates pattern → queries haps → schedules via OfflineAudioContext
 * with proper oscillators, ADSR, filters, panning.
 *
 * Usage: node src/runtime/offline-render-v2.mjs <input.js> [output.wav] [cycles] [bpm]
 */

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'fs';
import { createRequire } from 'module';
import path from 'path';

const require = createRequire(import.meta.url);

// ── Polyfill Web Audio for Node.js ──
const nwa = require('node-web-audio-api');
let _sharedCtx = null;
globalThis.AudioContext = class {
  constructor() {
    if (!_sharedCtx) {
      _sharedCtx = new nwa.OfflineAudioContext(2, 44100 * 600, 44100);
      _sharedCtx.resume = async () => {};
      _sharedCtx.close = async () => {};
    }
    return _sharedCtx;
  }
};
globalThis.OfflineAudioContext = nwa.OfflineAudioContext;
globalThis.AudioBuffer = nwa.AudioBuffer;
globalThis.AudioBufferSourceNode = nwa.AudioBufferSourceNode;
globalThis.GainNode = nwa.GainNode;
globalThis.OscillatorNode = nwa.OscillatorNode;
globalThis.BiquadFilterNode = nwa.BiquadFilterNode;
globalThis.StereoPannerNode = nwa.StereoPannerNode;
globalThis.DynamicsCompressorNode = nwa.DynamicsCompressorNode;
globalThis.ConvolverNode = nwa.ConvolverNode;
globalThis.DelayNode = nwa.DelayNode;
globalThis.WaveShaperNode = nwa.WaveShaperNode;
globalThis.AnalyserNode = nwa.AnalyserNode;

// Browser stubs
globalThis.window = {
  ...globalThis,
  addEventListener: () => {}, removeEventListener: () => {}, dispatchEvent: () => true,
  location: { href: '', origin: '', protocol: 'https:' },
  navigator: { userAgent: 'node' },
  requestAnimationFrame: cb => setTimeout(cb, 16), cancelAnimationFrame: clearTimeout,
  innerWidth: 800, innerHeight: 600, getComputedStyle: () => ({}),
};
globalThis.document = {
  createElement: () => ({ getContext: () => null, style: {}, setAttribute: () => {}, appendChild: () => {} }),
  body: { appendChild: () => {}, removeChild: () => {} },
  addEventListener: () => {}, removeEventListener: () => {}, dispatchEvent: () => true,
  createEvent: () => ({ initEvent: () => {} }),
  head: { appendChild: () => {} }, querySelectorAll: () => [], querySelector: () => null,
};
globalThis.addEventListener = () => {};
globalThis.removeEventListener = () => {};

// ── Parse args ──
const input = process.argv[2];
const output = process.argv[3] || 'output.wav';
const cycles = parseInt(process.argv[4] || '8');
const bpm = parseInt(process.argv[5] || '120');

if (!input) {
  console.error('Usage: node src/runtime/offline-render-v2.mjs <input.js> [output.wav] [cycles] [bpm]');
  process.exit(1);
}

const cps = bpm / 60 / 4;
const duration = cycles / cps;
const sampleRate = 44100;
const totalSamples = Math.ceil(duration * sampleRate);

console.log(`Offline render: ${input} → ${output}`);
console.log(`  Cycles: ${cycles}, BPM: ${bpm}, CPS: ${cps.toFixed(3)}, Duration: ${duration.toFixed(1)}s`);

// ── Load Strudel ──
console.log('Loading Strudel...');
const core = await import('@strudel/core');
const mini = await import('@strudel/mini');
try { await import('@strudel/tonal'); } catch (e) { /* optional */ }

// CRITICAL: Manually register mini notation parser on the Pattern class.
// The dist bundles can have separate module instances, so mini's auto-registration
// may target a different Pattern. Same class of bug as openclaw/openclaw#22790.
if (core.setStringParser && mini.mini) {
  core.setStringParser(mini.mini);
}

// Register ALL Strudel exports (functions, signals, constants) on globalThis
let cpmValue = bpm / 4;
for (const [key, val] of Object.entries(core)) {
  globalThis[key] = val;
}
globalThis.setcpm = (v) => { cpmValue = v; };
globalThis.setcps = (v) => { cpmValue = v * 60; };
globalThis.samples = () => {};
globalThis.hush = () => {};

// Browser-only methods to strip from patterns before headless evaluation
const vizMethods = ['pianoroll', '_pianoroll', 'spiral', '_spiral', 'scope', '_scope', 'draw', '_draw'];

/**
 * Strip browser-only visualization methods using balanced-parenthesis scanning.
 * Handles nested parens, multi-line args, and string literals correctly.
 * e.g. `.pianoroll({ fold: 1, labels: true })` → removed
 *
 * Approach: find `.methodName(` then count balanced parens to find the close.
 * This is more reliable than regex for nested/multi-line args (fixes #4).
 */
function stripVizMethods(code) {
  for (const method of vizMethods) {
    // Match .method( or ._method( — we need to find each occurrence and remove it
    const pattern = new RegExp(`\\.(${method})\\s*\\(`, 'g');
    let match;
    while ((match = pattern.exec(code)) !== null) {
      const dotStart = match.index; // position of the '.'
      const parenStart = code.indexOf('(', dotStart + method.length + 1);
      if (parenStart === -1) continue;

      // Scan for balanced close paren, respecting strings
      let depth = 1;
      let i = parenStart + 1;
      let inStr = null; // null, "'", '"', '`'
      while (i < code.length && depth > 0) {
        const ch = code[i];
        if (inStr) {
          if (ch === '\\') { i += 2; continue; } // skip escaped chars
          if (ch === inStr) inStr = null;
        } else {
          if (ch === "'" || ch === '"' || ch === '`') inStr = ch;
          else if (ch === '(') depth++;
          else if (ch === ')') depth--;
        }
        i++;
      }
      if (depth === 0) {
        // Remove from dot to closing paren (inclusive)
        code = code.slice(0, dotStart) + code.slice(i);
        // Reset regex since string changed
        pattern.lastIndex = dotStart;
      }
    }
  }
  return code;
}

console.log('  ✅ Strudel loaded');

// ── Evaluate pattern ──
console.log('Evaluating pattern...');
let patternCode = readFileSync(input, 'utf8')
  .replace(/^\/\/ @\w+.*/gm, '')
  .trim();

// Strip visualization methods using balanced-paren scanner (fixes #4)
patternCode = stripVizMethods(patternCode);

// ── Security hardening: scrub sensitive globals before pattern eval ──
// Patterns are JS evaluated via new Function() in the current process.
// Remove access to environment variables and child_process to limit
// damage from malicious patterns. This is NOT a sandbox — patterns can
// still access fs, network, etc. For untrusted patterns, use a container.
const _savedEnv = process.env;
const _savedExec = process.execPath;
process.env = Object.freeze({ NODE_ENV: 'production' });
// Prevent require('child_process') by poisoning the module cache
const _savedCpModule = await import('module').then(m => {
  const orig = m.default._resolveFilename;
  m.default._resolveFilename = function(request, ...args) {
    if (request === 'child_process' || request === 'node:child_process') {
      throw new Error('child_process is blocked during pattern evaluation');
    }
    return orig.call(this, request, ...args);
  };
  return orig;
}).catch(() => null);

let pattern;
try {
  // Strudel patterns are typically: setcpm(...); stack(...).stuff()
  // The last expression is the pattern. We need to capture it.
  // Strategy: split into statements, wrap the last one in return.
  const lines = patternCode.split('\n');

  // Find the last non-empty, non-comment line that starts a pattern expression
  // Usually starts with stack(, note(, s(, n(, etc.
  let lastExprStart = -1;
  let depth = 0;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line || line.startsWith('//')) continue;

    // Track if this line starts a new top-level expression
    if (depth === 0 && /^(stack|note|s|n|seq|cat|sequence|arrange|slowcat|fastcat)\s*\(/.test(line)) {
      lastExprStart = i;
    }
    // Track paren depth
    for (const ch of line) {
      if (ch === '(') depth++;
      if (ch === ')') depth--;
    }
  }

  if (lastExprStart >= 0) {
    const setup = lines.slice(0, lastExprStart).join('\n');
    const expr = lines.slice(lastExprStart).join('\n');
    const wrapped = setup + '\nreturn ' + expr;
    const fn = new Function(wrapped);
    pattern = fn();
  } else {
    // Try as-is, then with return
    try {
      const fn = new Function(patternCode);
      pattern = fn();
    } catch {
      const fn = new Function('return ' + patternCode);
      pattern = fn();
    }
  }
} catch (e) {
  console.error('  ❌ Pattern eval failed:', e.message);
  process.env = _savedEnv;  // Restore before exit
  process.exit(1);
} finally {
  // Restore environment after pattern evaluation
  process.env = _savedEnv;
  // Restore module resolution
  if (_savedCpModule) {
    import('module').then(m => { m.default._resolveFilename = _savedCpModule; }).catch(() => {});
  }
}

if (!pattern || typeof pattern.queryArc !== 'function') {
  console.error('  ❌ Pattern did not return a queryable pattern. Got:', typeof pattern);
  process.exit(1);
}

// ── Query haps ──
const actualCps = cpmValue / 60;
const actualDuration = cycles / actualCps;
const actualSamples = Math.ceil(actualDuration * sampleRate);

console.log(`  Using CPS: ${actualCps.toFixed(3)} (${cpmValue * 4} BPM), Duration: ${actualDuration.toFixed(1)}s`);

const haps = pattern.queryArc(0, cycles);
console.log(`  Found ${haps.length} haps`);

if (haps.length === 0) {
  console.error('  ⚠️ No haps. Output will be silence.');
}

// ── Load samples ──
const SAMPLES_DIR = path.resolve(
  import.meta.dirname || path.dirname(new URL(import.meta.url).pathname),
  '../../samples'
);
const sampleBuffers = new Map(); // "bd:0" → AudioBuffer

function loadWavToBuffer(filePath, ctx) {
  const raw = readFileSync(filePath);
  // Parse WAV header
  const view = new DataView(raw.buffer, raw.byteOffset, raw.byteLength);
  if (raw.toString('ascii', 0, 4) !== 'RIFF') return null;

  const channels = view.getUint16(22, true);
  const sr = view.getUint32(24, true);
  const bitsPerSample = view.getUint16(34, true);

  // Find data chunk
  let dataOffset = 12;
  while (dataOffset < raw.length - 8) {
    const chunkId = raw.toString('ascii', dataOffset, dataOffset + 4);
    const chunkSize = view.getUint32(dataOffset + 4, true);
    if (chunkId === 'data') {
      dataOffset += 8;
      const numSamples = chunkSize / (bitsPerSample / 8) / channels;
      const audioBuffer = ctx.createBuffer(channels, numSamples, sr);

      for (let ch = 0; ch < channels; ch++) {
        const channelData = audioBuffer.getChannelData(ch);
        for (let i = 0; i < numSamples; i++) {
          const byteIndex = dataOffset + (i * channels + ch) * (bitsPerSample / 8);
          if (bitsPerSample === 16) {
            channelData[i] = view.getInt16(byteIndex, true) / 32768;
          } else if (bitsPerSample === 24) {
            const s = (view.getUint8(byteIndex) | (view.getUint8(byteIndex+1) << 8) | (view.getInt8(byteIndex+2) << 16));
            channelData[i] = s / 8388608;
          }
        }
      }
      return audioBuffer;
    }
    dataOffset += 8 + chunkSize;
  }
  return null;
}

if (existsSync(SAMPLES_DIR)) {
  console.log('Loading samples...');
  let sampleCount = 0;
  // Preload a temporary OfflineAudioContext for buffer creation
  const tmpCtx = new nwa.OfflineAudioContext(2, 1, sampleRate);

  for (const dir of readdirSync(SAMPLES_DIR)) {
    const dirPath = path.join(SAMPLES_DIR, dir);
    try {
      const files = readdirSync(dirPath).filter(f => f.endsWith('.wav') || f.endsWith('.WAV')).sort();
      for (let i = 0; i < files.length; i++) {
        const buf = loadWavToBuffer(path.join(dirPath, files[i]), tmpCtx);
        if (buf) {
          sampleBuffers.set(`${dir}:${i}`, buf);
          if (i === 0) sampleBuffers.set(dir, buf); // default (index 0)
          sampleCount++;
        }
      }
    } catch { /* not a directory */ }
  }
  console.log(`  ✅ ${sampleCount} samples loaded from ${sampleBuffers.size} entries`);
} else {
  console.log('  ⚠️ No samples directory found. Sample-based sounds will be silent.');
}

// ── Render to OfflineAudioContext ──
console.log('Rendering...');
const offCtx = new nwa.OfflineAudioContext(2, actualSamples, sampleRate);

// Master compressor for clean output
// Gentler settings to avoid pumping artifacts on vocal material (#22)
const compressor = offCtx.createDynamicsCompressor();
compressor.threshold.setValueAtTime(-12, 0);
compressor.knee.setValueAtTime(10, 0);
compressor.ratio.setValueAtTime(4, 0);
compressor.connect(offCtx.destination);

// Oscillator type map (outside loop for performance)
const waveMap = {
  sine: 'sine', triangle: 'triangle', square: 'square',
  sawtooth: 'sawtooth', saw: 'sawtooth', tri: 'triangle',
  piano: 'triangle', bass: 'sawtooth', pluck: 'triangle',
  supersaw: 'sawtooth', supersquare: 'square', organ: 'sine',
};

const warnedSounds = new Set(); // track warned sound names to avoid spam
let scheduled = 0;
for (const hap of haps) {
  // Skip continuation fragments — only schedule onset haps.
  // Strudel's queryArc splits long events at integer cycle boundaries,
  // producing multiple haps with the same whole arc but different part arcs.
  // hasOnset() is true only for the first fragment (part.begin === whole.begin).
  // Without this filter, samples get stacked N times at the same start time (#22 v7).
  if (typeof hap.hasOnset === 'function' && !hap.hasOnset()) continue;

  const startCycle = hap.whole?.begin ?? hap.part?.begin ?? 0;
  const endCycle = hap.whole?.end ?? hap.part?.end ?? startCycle + 0.25;
  const hapStart = startCycle / actualCps;
  const hapDur = (endCycle - startCycle) / actualCps;

  if (hapStart >= actualDuration || hapStart < 0) continue;

  const v = hap.value;
  if (typeof v !== 'object' || v === null) continue;

  const gain = Math.min(v.gain ?? 0.3, 1.0);
  if (gain <= 0.001) continue; // Skip silent haps (saves memory on masked layers)
  const sound = v.s || '';
  const nVal = v.n !== undefined ? Math.round(Number(v.n)) : 0;
  const lpf = v.lpf ?? v.cutoff ?? 6000;
  const attack = v.attack ?? 0.005;
  const decay = v.decay ?? 0.1;
  const sustain = v.sustain ?? 0.7;
  const release = v.release ?? 0.3;
  const pan = v.pan ?? 0.5;

  // Check if this is a sample-based sound
  const sampleKey = `${sound}:${nVal}`;
  const sampleBuf = sampleBuffers.get(sampleKey) || sampleBuffers.get(sound);

  const isSynthSound = waveMap[sound] !== undefined;

  // Resolve note → frequency (for synth sounds)
  let freq = null;
  if (v.freq) freq = v.freq;
  else if (v.note) freq = noteToFreq(v.note);
  // TODO: resolve scale degree to freq using tonal's Scale.get() + degree mapping
  // Currently falls through to 440Hz for unresolved scale degrees
  else if (v.n !== undefined && isSynthSound) freq = 440;

  // Skip if neither sample nor synth — warn on unrecognized sounds
  if (!sampleBuf && !isSynthSound && sound) {
    if (!warnedSounds.has(sound)) {
      console.warn(`  ⚠️ Unrecognized sound "${sound}" — falling back to 440Hz synth`);
      warnedSounds.add(sound);
    }
    if (!freq) freq = 440;
  } else if (!sampleBuf && !freq && !isSynthSound) {
    if (!freq) freq = 440; // last resort fallback
  }

  try {
    const endTime = hapStart + hapDur;

    // Gain node
    const gn = offCtx.createGain();

    // Filter
    const flt = offCtx.createBiquadFilter();
    flt.type = 'lowpass';
    flt.frequency.setValueAtTime(Math.min(lpf, sampleRate / 2 - 100), hapStart);
    flt.Q.setValueAtTime(1.5, hapStart);

    // Panner
    const pnr = offCtx.createStereoPanner();
    pnr.pan.setValueAtTime((pan - 0.5) * 2, hapStart);

    if (sampleBuf) {
      // ── Sample playback ──
      const src = offCtx.createBufferSource();
      src.buffer = sampleBuf;

      // When clip=1, let the sample play its full natural duration
      // instead of cutting at the cycle/hap boundary (#22, dev#1)
      const clipVal = v.clip !== undefined ? Number(v.clip) : 0;

      // loopAt support: if loopAt is set OR the hap window exceeds the sample
      // length, enable looping so the sample fills the entire hap duration.
      // This is the offline-renderer counterpart to Ronan's synth.mjs loopfix.
      const loopAtVal = v.loopAt;
      const shouldLoop = loopAtVal != null || hapDur > sampleBuf.duration;

      if (shouldLoop) {
        src.loop = true;
        src.loopStart = 0;
        src.loopEnd = sampleBuf.duration;
      }

      const effectiveEnd = shouldLoop
        ? endTime  // fill the entire hap window when looping
        : clipVal >= 1
          ? hapStart + sampleBuf.duration
          : Math.min(endTime, hapStart + sampleBuf.duration);

      // Crossfade envelope: 30ms fade-in, 50ms fade-out (#22)
      // Replaces instant-on + 20ms fade-out which caused hard splice clicks
      const fadeIn = 0.03;   // 30ms
      const fadeOut = 0.05;  // 50ms
      const sampleEnd = effectiveEnd;
      gn.gain.setValueAtTime(0, hapStart);
      gn.gain.linearRampToValueAtTime(gain, hapStart + fadeIn);
      gn.gain.setValueAtTime(gain, Math.max(hapStart + fadeIn, sampleEnd - fadeOut));
      gn.gain.linearRampToValueAtTime(0, sampleEnd);

      // Apply playback rate if note specified (pitch shifting)
      if (v.note) {
        const semitones = noteToSemitones(v.note);
        if (semitones !== 0) src.playbackRate.setValueAtTime(Math.pow(2, semitones / 12), hapStart);
      }
      if (v.speed) src.playbackRate.setValueAtTime(Math.abs(v.speed), hapStart);

      src.connect(flt);
      flt.connect(gn);
      gn.connect(pnr);
      pnr.connect(compressor);

      src.start(hapStart);
      src.stop(sampleEnd + 0.05);
    } else {
      // ── Oscillator synth ──
      if (!freq) freq = 440;
      const oscType = waveMap[sound] || 'triangle';

      const osc = offCtx.createOscillator();
      osc.type = oscType;
      osc.frequency.setValueAtTime(freq, hapStart);

      // Slight detune for richness on saw/square
      if (oscType === 'sawtooth' || oscType === 'square') {
        osc.detune.setValueAtTime(Math.random() * 10 - 5, hapStart);
      }

      // ADSR envelope
      gn.gain.setValueAtTime(0, hapStart);
      gn.gain.linearRampToValueAtTime(gain, Math.min(hapStart + attack, endTime));
      gn.gain.linearRampToValueAtTime(gain * sustain, Math.min(hapStart + attack + decay, endTime));
      if (endTime - release > hapStart + attack + decay) {
        gn.gain.setValueAtTime(gain * sustain, endTime - release);
      }
      gn.gain.linearRampToValueAtTime(0, endTime + 0.01);

      osc.connect(flt);
      flt.connect(gn);
      gn.connect(pnr);
      pnr.connect(compressor);

      osc.start(hapStart);
      osc.stop(endTime + 0.05);
    }

    scheduled++;
  } catch (e) {
    // Skip problematic haps
  }
}

console.log(`  Scheduled ${scheduled}/${haps.length} haps`);

if (scheduled === 0) {
  console.error('  ❌ Nothing to render.');
  process.exit(1);
}

const buf = await offCtx.startRendering();
console.log(`  ✅ Rendered: ${buf.length} samples (${(buf.length / sampleRate).toFixed(1)}s)`);

// ── Master fade-out ──
// Apply 2-second linear fade-out to the end of the rendered buffer.
// Prevents the hard cliff exit heard in v7 (#22).
const fadeOutSeconds = 2;
const fadeOutSamples = Math.min(Math.ceil(fadeOutSeconds * sampleRate), buf.length);
const fadeOutStart = buf.length - fadeOutSamples;
for (let ch = 0; ch < buf.numberOfChannels; ch++) {
  const channelData = buf.getChannelData(ch);
  for (let i = 0; i < fadeOutSamples; i++) {
    const gain = 1 - (i / fadeOutSamples); // linear ramp from 1 → 0
    channelData[fadeOutStart + i] *= gain;
  }
}
console.log(`  ✅ Applied ${fadeOutSeconds}s master fade-out (${fadeOutSamples} samples)`);

// ── Write WAV ──
const left = buf.getChannelData(0);
const right = buf.numberOfChannels > 1 ? buf.getChannelData(1) : left;

const pcm = Buffer.alloc(buf.length * 4);
for (let i = 0; i < buf.length; i++) {
  pcm.writeInt16LE(Math.round(Math.max(-1, Math.min(1, left[i])) * 32767), i * 4);
  pcm.writeInt16LE(Math.round(Math.max(-1, Math.min(1, right[i])) * 32767), i * 4 + 2);
}

const wav = makeWav(pcm, sampleRate, 2, 16);
writeFileSync(output, wav);
console.log(`✅ ${output} (${(wav.length / 1024 / 1024).toFixed(1)}MB)`);
process.exit(0);

// ── Helpers ──
function noteToSemitones(note) {
  // Returns semitone offset from C4 (for sample pitch shifting)
  if (typeof note === 'number') return note - 60; // MIDI
  const m = String(note).match(/^([a-gA-G])(#|b|s)?(\d+)?$/);
  if (!m) return 0;
  const map = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
  let semi = map[m[1].toLowerCase()] ?? 0;
  if (m[2] === '#' || m[2] === 's') semi++;
  if (m[2] === 'b') semi--;
  const oct = parseInt(m[3] ?? '4');
  return semi + (oct * 12) - 60; // offset from C4
}

function noteToFreq(note) {
  if (typeof note === 'number') return note;
  const m = String(note).match(/^([a-gA-G])(#|b|s)?(\d+)?$/);
  if (!m) return 440;
  const map = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
  let semi = map[m[1].toLowerCase()] ?? 0;
  if (m[2] === '#' || m[2] === 's') semi++;
  if (m[2] === 'b') semi--;
  const oct = parseInt(m[3] ?? '4');
  return 440 * Math.pow(2, (semi - 9 + (oct - 4) * 12) / 12);
}

function makeWav(pcm, sr, ch, bits) {
  const h = Buffer.alloc(44);
  h.write('RIFF', 0);
  h.writeUInt32LE(36 + pcm.length, 4);
  h.write('WAVE', 8);
  h.write('fmt ', 12);
  h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20);
  h.writeUInt16LE(ch, 22);
  h.writeUInt32LE(sr, 24);
  h.writeUInt32LE(sr * ch * bits / 8, 28);
  h.writeUInt16LE(ch * bits / 8, 32);
  h.writeUInt16LE(bits, 34);
  h.write('data', 36);
  h.writeUInt32LE(pcm.length, 40);
  return Buffer.concat([h, pcm]);
}

#!/usr/bin/env node
/**
 * Smoke test: verify Strudel loads, mini notation parses, samples exist.
 */
import { existsSync, readdirSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '../..');
let passed = 0, failed = 0;

function check(name, ok) {
  if (ok) { console.log(`  ✅ ${name}`); passed++; }
  else { console.log(`  ❌ ${name}`); failed++; }
}

console.log('Strudel Music — Smoke Test\n');

// 1. Core imports
const core = await import('@strudel/core');
check('@strudel/core loaded', !!core.Pattern);

const mini = await import('@strudel/mini');
check('@strudel/mini loaded', !!mini.mini);

// 2. String parser registration
core.setStringParser(mini.mini);
const p = core.note('c3 e3 g3');
const haps = p.queryArc(0, 1);
check(`Mini notation parsing (got ${haps.length} haps, expected 3)`, haps.length === 3);

// 3. Tonal
try {
  await import('@strudel/tonal');
  check('@strudel/tonal loaded', true);
} catch {
  check('@strudel/tonal loaded', false);
}

// 4. node-web-audio-api
const require = createRequire(import.meta.url);
try {
  const nwa = require('node-web-audio-api');
  check('node-web-audio-api (OfflineAudioContext)', !!nwa.OfflineAudioContext);
} catch (e) {
  check(`node-web-audio-api: ${e.message}`, false);
}

// 5. Samples
const samplesDir = resolve(root, 'samples');
check('Samples directory exists', existsSync(samplesDir));
if (existsSync(samplesDir)) {
  const dirs = readdirSync(samplesDir).filter(d => {
    try { return readdirSync(resolve(samplesDir, d)).some(f => f.endsWith('.wav')); }
    catch { return false; }
  });
  check(`Sample sets loaded (${dirs.length} dirs, need ≥5)`, dirs.length >= 5);
  check('bd (bass drum) samples present', dirs.includes('bd'));
  check('sd (snare) samples present', dirs.includes('sd'));
  check('hh (hihat) samples present', dirs.includes('hh'));
}

// 6. Composition files
const compsDir = resolve(root, 'assets/compositions');
if (existsSync(compsDir)) {
  const comps = readdirSync(compsDir).filter(f => f.endsWith('.js'));
  check(`Compositions found (${comps.length} files, need ≥5)`, comps.length >= 5);
}

// 7. Discord voice deps (optional)
try {
  await import('@discordjs/voice');
  check('@discordjs/voice (VC streaming)', true);
} catch {
  check('@discordjs/voice (VC streaming, optional)', false);
}

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

// synth.mjs — Minimal software synthesizer for Strudel pattern events
// Renders pattern haps to PCM audio without any browser/WebAudio dependency.
// Supports oscillator synthesis AND sample playback from WAV files.

import { readFileSync, readdirSync, existsSync } from "node:fs";
import path from "node:path";

const TWO_PI = Math.PI * 2;

// ──────────────────────────────────────────────────
// Sample loading — reads WAV files from samples/ dir
// ──────────────────────────────────────────────────

const sampleCache = new Map();  // "bd:0" → Float32Array

/**
 * Load all WAV samples from a samples directory.
 * Structure: samplesDir/<name>/<files>.wav
 * Each dir becomes a sample bank (bd, sd, hh, etc.)
 */
export function loadSamples(samplesDir) {
  if (!existsSync(samplesDir)) return;
  for (const dir of readdirSync(samplesDir, { withFileTypes: true })) {
    if (!dir.isDirectory()) continue;
    const bankPath = path.join(samplesDir, dir.name);
    const files = readdirSync(bankPath)
      .filter(f => /\.wav$/i.test(f))
      .sort();
    files.forEach((f, idx) => {
      const key = `${dir.name}:${idx}`;
      try {
        sampleCache.set(key, readWavPcm(path.join(bankPath, f)));
      } catch { /* skip unreadable files */ }
    });
  }
  const banks = new Set([...sampleCache.keys()].map(k => k.split(':')[0]));
  console.error(`  Samples loaded: ${sampleCache.size} files in ${banks.size} banks`);
}

/**
 * Read a WAV file and return mono Float32Array of samples.
 * Supports 16-bit and 24-bit PCM.
 */
function readWavPcm(filePath) {
  const buf = readFileSync(filePath);
  // Find 'fmt ' chunk
  let fmtOffset = buf.indexOf('fmt ', 0, 'ascii');
  if (fmtOffset < 0) throw new Error('No fmt chunk');
  fmtOffset += 4; // skip 'fmt '
  const fmtSize = buf.readUInt32LE(fmtOffset); fmtOffset += 4;
  const audioFormat = buf.readUInt16LE(fmtOffset);
  const numChannels = buf.readUInt16LE(fmtOffset + 2);
  const sampleRate = buf.readUInt32LE(fmtOffset + 4);
  const bitsPerSample = buf.readUInt16LE(fmtOffset + 14);

  if (audioFormat !== 1) throw new Error(`Unsupported format: ${audioFormat}`);

  // Find 'data' chunk
  let dataOffset = buf.indexOf('data', fmtOffset, 'ascii');
  if (dataOffset < 0) throw new Error('No data chunk');
  dataOffset += 4; // skip 'data'
  const dataSize = buf.readUInt32LE(dataOffset); dataOffset += 4;

  const bytesPerSample = bitsPerSample / 8;
  const numSamples = Math.floor(dataSize / (bytesPerSample * numChannels));
  const pcm = new Float32Array(numSamples);

  for (let i = 0; i < numSamples; i++) {
    const offset = dataOffset + i * numChannels * bytesPerSample;
    // Read first channel only (mono mixdown)
    if (bitsPerSample === 16) {
      pcm[i] = buf.readInt16LE(offset) / 32768;
    } else if (bitsPerSample === 24) {
      const val = buf.readUIntLE(offset, 3);
      pcm[i] = (val > 0x7fffff ? val - 0x1000000 : val) / 8388608;
    } else if (bitsPerSample === 8) {
      pcm[i] = (buf.readUInt8(offset) - 128) / 128;
    }
  }
  return pcm;
}

/**
 * Get a sample by bank name and index (n).
 * Returns Float32Array or null.
 */
function getSample(bankName, n = 0) {
  const key = `${bankName}:${n}`;
  if (sampleCache.has(key)) return sampleCache.get(key);
  // Try index 0 if requested index doesn't exist
  const fallback = `${bankName}:0`;
  return sampleCache.get(fallback) ?? null;
}

/** Check if a name is a known oscillator type */
function isOscillator(name) {
  return name in oscillators;
}

/**
 * Convert a note name or MIDI number to frequency in Hz.
 */
export function noteToFreq(note) {
  if (typeof note === 'number') {
    return 440 * Math.pow(2, (note - 69) / 12);
  }
  if (typeof note === 'string') {
    const match = note.match(/^([a-gA-G])([#b]?)(\d+)$/);
    if (!match) return 440;
    const names = { c: 0, d: 2, e: 4, f: 5, g: 7, a: 9, b: 11 };
    let semitone = names[match[1].toLowerCase()] ?? 0;
    if (match[2] === '#') semitone += 1;
    if (match[2] === 'b') semitone -= 1;
    const octave = parseInt(match[3], 10);
    const midi = (octave + 1) * 12 + semitone;
    return 440 * Math.pow(2, (midi - 69) / 12);
  }
  return 440;
}

/**
 * Oscillator functions: sample → [-1, 1]
 */
const oscillators = {
  sine: (phase) => Math.sin(TWO_PI * phase),
  square: (phase) => (phase % 1) < 0.5 ? 1 : -1,
  sawtooth: (phase) => 2 * (phase % 1) - 1,
  triangle: (phase) => {
    const p = phase % 1;
    return p < 0.5 ? 4 * p - 1 : 3 - 4 * p;
  },
};

/**
 * Simple ADSR envelope.
 */
function envelope(t, duration, attack = 0.01, decay = 0.1, sustain = 0.7, release = 0.05) {
  if (t < 0) return 0;
  if (t < attack) return t / attack;
  if (t < attack + decay) return 1 - (1 - sustain) * ((t - attack) / decay);
  if (t < duration - release) return sustain;
  if (t < duration) return sustain * (1 - (t - (duration - release)) / release);
  return 0;
}

/**
 * Simple low-pass filter (one-pole IIR).
 */
function lpfCoeff(cutoffHz, sampleRate) {
  const dt = 1 / sampleRate;
  const rc = 1 / (TWO_PI * cutoffHz);
  return dt / (rc + dt);
}

/**
 * Extract haps (events) from a Strudel pattern for a given time span.
 */
export function queryPattern(pattern, startCycle, endCycle) {
  const haps = [];
  try {
    // Strudel Pattern.queryArc returns haps
    const result = pattern.queryArc(startCycle, endCycle);
    if (Array.isArray(result)) {
      return result;
    }
    // Some versions return an iterator
    if (result && typeof result[Symbol.iterator] === 'function') {
      for (const hap of result) {
        haps.push(hap);
      }
    }
  } catch (e) {
    // Fallback: try firstCycle/lastCycle
    try {
      for (let c = Math.floor(startCycle); c < Math.ceil(endCycle); c++) {
        const cycleHaps = pattern.firstCycle?.(c) ?? [];
        haps.push(...cycleHaps);
      }
    } catch {
      // Pattern may not support this query method
    }
  }
  return haps;
}

/**
 * Render a set of haps to stereo PCM float arrays.
 *
 * @param {Array} haps - Strudel hap objects with .whole, .value
 * @param {number} durationSec - Total duration in seconds
 * @param {number} sampleRate - Sample rate (default 44100)
 * @returns {[Float32Array, Float32Array]} - [left, right] channels
 */
export function renderHapsToAudio(haps, durationSec, sampleRate = 44100) {
  const numSamples = Math.ceil(durationSec * sampleRate);
  const left = new Float32Array(numSamples);
  const right = new Float32Array(numSamples);

  for (const hap of haps) {
    if (!hap?.whole) continue;

    const value = hap.value ?? {};
    const startSec = Number(hap.whole.begin) * durationSec / (Number(hap.whole.end) > 0 ? Number(hap.whole.end) : 1);
    const endSec = Number(hap.whole.end) * durationSec / (Number(hap.whole.end) > 0 ? Number(hap.whole.end) : 1);

    const hapStartSec = hap._renderStart ?? startSec;
    const hapEndSec = hap._renderEnd ?? endSec;
    const hapDuration = hapEndSec - hapStartSec;
    if (hapDuration <= 0) continue;

    // Extract common parameters
    const gain = value.gain ?? 0.3;
    const pan = value.pan ?? 0.5;
    const cutoff = value.lpf ?? value.cutoff ?? 20000;
    const hpf = value.hpf ?? 0;
    const sName = value.s ?? value.wave ?? 'sine';
    const sampleN = value.n ?? 0;

    const startSample = Math.max(0, Math.floor(hapStartSec * sampleRate));
    const panL = Math.cos(pan * Math.PI / 2);
    const panR = Math.sin(pan * Math.PI / 2);

    // Route: sample playback vs oscillator synthesis
    if (!isOscillator(sName) && !value.note && !value.freq) {
      // ── SAMPLE PLAYBACK ──
      const pcm = getSample(sName, sampleN);
      if (!pcm) continue;  // unknown sample, skip silently

      const sampleLen = pcm.length;

      // Determine playback speed (for pitch shifting via .speed())
      const speed = value.speed ?? 1;

      // Determine how long this hap should play:
      // If loopAt is set, or if clip/slow create a window longer than the sample,
      // loop the sample to fill the entire hap duration.
      // Otherwise play once (one-shot).
      const hapDurationSamples = Math.ceil(hapDuration * sampleRate);
      const loopAt = value.loopAt;
      const clip = value.clip;

      // Loop if: loopAt is set, OR the hap duration exceeds the sample length
      // (which means .slow() created a window the sample can't fill alone)
      const shouldLoop = loopAt != null || hapDurationSamples > sampleLen;

      const endSampleIdx = shouldLoop
        ? Math.min(numSamples, startSample + hapDurationSamples)
        : Math.min(numSamples, startSample + Math.ceil(sampleLen / Math.abs(speed || 1)));

      const alpha = lpfCoeff(Math.min(cutoff, sampleRate / 2), sampleRate);
      const hpfAlpha = hpf > 0 ? lpfCoeff(Math.min(hpf, sampleRate / 2), sampleRate) : 0;
      let filteredL = 0, filteredR = 0;
      let hpPrevL = 0, hpPrevR = 0;

      // Crossfade length for loop points (avoid clicks at loop boundary)
      const xfadeSamples = Math.min(2205, Math.floor(sampleLen * 0.05)); // 50ms or 5% of sample

      for (let i = startSample; i < endSampleIdx; i++) {
        const srcIdxRaw = (i - startSample) * Math.abs(speed || 1);
        let raw;

        if (shouldLoop && sampleLen > 0) {
          // Loop with crossfade at boundaries
          const pos = srcIdxRaw % sampleLen;
          const idx = Math.floor(pos);
          const frac = pos - idx;

          // Linear interpolation for smooth playback at non-integer speeds
          const s0 = pcm[idx % sampleLen];
          const s1 = pcm[(idx + 1) % sampleLen];
          let sample = s0 + frac * (s1 - s0);

          // Crossfade near loop boundary to avoid click
          const distToEnd = sampleLen - pos;
          if (distToEnd < xfadeSamples && xfadeSamples > 0) {
            const fadeOut = distToEnd / xfadeSamples;
            const fadeIn = 1 - fadeOut;
            // Blend with beginning of sample
            const loopPos = pos - (sampleLen - xfadeSamples);
            const loopIdx = Math.max(0, Math.floor(loopPos));
            const loopSample = pcm[loopIdx % sampleLen];
            sample = sample * fadeOut + loopSample * fadeIn;
          }

          raw = sample * gain;
        } else {
          // One-shot playback
          const srcIdx = Math.floor(srcIdxRaw);
          if (srcIdx >= sampleLen) break;
          raw = pcm[srcIdx] * gain;
        }

        // LPF
        filteredL = filteredL + alpha * (raw * panL - filteredL);
        filteredR = filteredR + alpha * (raw * panR - filteredR);

        // Optional HPF (one-pole)
        if (hpf > 0) {
          const outL = filteredL - hpPrevL; hpPrevL = filteredL; filteredL = outL;
          const outR = filteredR - hpPrevR; hpPrevR = filteredR; filteredR = outR;
        }

        left[i] += filteredL;
        right[i] += filteredR;
      }
    } else {
      // ── OSCILLATOR SYNTHESIS ──
      const oscName = isOscillator(sName) ? sName : 'sine';
      const oscFn = oscillators[oscName];
      const freq = value.freq ?? noteToFreq(value.note ?? value.n ?? 60);
      const attack = value.attack ?? 0.01;
      const decay = value.decay ?? 0.1;
      const sustain = value.sustain ?? 0.7;
      const release = value.release ?? 0.05;

      const endSampleIdx = Math.min(numSamples, Math.ceil(hapEndSec * sampleRate));

      const alpha = lpfCoeff(Math.min(cutoff, sampleRate / 2), sampleRate);
      const hpfAlpha = hpf > 0 ? lpfCoeff(Math.min(hpf, sampleRate / 2), sampleRate) : 0;
      let filteredL = 0, filteredR = 0;
      let hpPrevL = 0, hpPrevR = 0;
      let phase = 0;
      const phaseInc = freq / sampleRate;

      for (let i = startSample; i < endSampleIdx; i++) {
        const t = (i - startSample) / sampleRate;
        const env = envelope(t, hapDuration, attack, decay, sustain, release);
        const raw = oscFn(phase) * env * gain;
        phase += phaseInc;

        // LPF
        filteredL = filteredL + alpha * (raw * panL - filteredL);
        filteredR = filteredR + alpha * (raw * panR - filteredR);

        // Optional HPF
        if (hpf > 0) {
          const outL = filteredL - hpPrevL; hpPrevL = filteredL; filteredL = outL;
          const outR = filteredR - hpPrevR; hpPrevR = filteredR; filteredR = outR;
        }

        left[i] += filteredL;
        right[i] += filteredR;
      }
    }
  }

  // Soft clip to prevent clipping
  for (let i = 0; i < numSamples; i++) {
    left[i] = Math.tanh(left[i]);
    right[i] = Math.tanh(right[i]);
  }

  return [left, right];
}

#!/usr/bin/env node

import { createWriteStream, existsSync } from "node:fs";
import { spawn } from "node:child_process";
import process from "node:process";

function usage() {
  console.error("Usage: node src/stream/pipe-to-vc.mjs <input.wav> [bridge-endpoint] [--file]");
}

const rawArgs = process.argv.slice(2);
const fileOutput = rawArgs.includes("--file");
const args = rawArgs.filter((arg) => arg !== "--file");
const inputWav = args[0];
const bridgeEndpoint = args[1] || process.env.DISCORD_VC_BRIDGE_ENDPOINT;

if (!inputWav) {
  usage();
  process.exit(1);
}

if (!existsSync(inputWav)) {
  console.error(`Input WAV not found: ${inputWav}`);
  process.exit(1);
}

if (bridgeEndpoint) {
  console.error(`Bridge endpoint: ${bridgeEndpoint}`);
}

const ffmpegArgs = [
  "-i",
  inputWav,
  "-c:a",
  "libopus",
  "-b:a",
  "128k",
  "-ar",
  "48000",
  "-f",
  "opus",
  "pipe:1",
];

const ffmpeg = spawn("ffmpeg", ffmpegArgs, {
  stdio: ["ignore", "pipe", "inherit"],
});

if (fileOutput) {
  const out = createWriteStream("output.opus");
  ffmpeg.stdout.pipe(out);
  out.on("finish", () => {
    console.error("Wrote output.opus");
  });
} else {
  ffmpeg.stdout.pipe(process.stdout);
}

ffmpeg.on("error", (error) => {
  console.error(`Failed to launch ffmpeg: ${error.message}`);
  process.exit(1);
});

ffmpeg.on("close", (code) => {
  process.exit(code ?? 1);
});
